--
-- Disparadores `integraciones_usuario`
--
DELIMITER $$
CREATE TRIGGER `trg_integraciones_usuario_actualizado` BEFORE UPDATE ON `integraciones_usuario` FOR EACH ROW BEGIN
  SET NEW.actualizado_at = CURRENT_TIMESTAMP;
END
$$
DELIMITER ;

