--
-- Disparadores `modulos_nova`
--
DELIMITER $$
CREATE TRIGGER `trg_modulos_nova_actualizado` BEFORE UPDATE ON `modulos_nova` FOR EACH ROW BEGIN
  SET NEW.actualizado_at = CURRENT_TIMESTAMP;
END
$$
DELIMITER ;

