--
-- Disparadores `usuarios_nova`
--
DELIMITER $$
CREATE TRIGGER `trg_usuarios_nova_actualizado` BEFORE UPDATE ON `usuarios_nova` FOR EACH ROW BEGIN
  SET NEW.actualizado_at = CURRENT_TIMESTAMP;
END
$$
DELIMITER ;

--
-- Índices para tablas volcadas
--

--
-- Indices de la tabla `catalogos_modulo`
--
ALTER TABLE `catalogos_modulo`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `uq_catalogo_modulo_item` (`modulo_id`,`tipo`,`clave_externa`),
  ADD KEY `idx_catalogos_tipo` (`tipo`),
  ADD KEY `idx_catalogos_nombre` (`nombre`);

--
