  ADD PRIMARY KEY (`id`);

--
-- Indices de la tabla `modulos_nova`
--
ALTER TABLE `modulos_nova`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `uq_modulos_nova_clave` (`clave_modulo`),
